10	/**
11	 * Counts the owners already registered in the new owner's city, comparing case-insensitively,
12	 * and publishes the total so the per-city rules share a single accumulation. Runs before the
13	 * owner is saved, so the count excludes the owner being created; both {@link EnsureCityCapacity}
14	 * (the hard limit) and {@link AssignCapacityWarning} (the soft warning) read the published value
15	 * rather than re-scanning the table.
16	 */
17	public class CountCityOwners {
18	
19	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository,
20	            @Qualified("cityOwnerCount") Out<Integer> cityOwnerCount) {
21	        String city = request.getCity();
22	        int count = 0;
23	        for (Owner existing : ownerRepository.findAll()) {
24	            if (city.equalsIgnoreCase(existing.getCity())) {
25	                count++;
26	            }
27	        }
28	        cityOwnerCount.set(count);
29	    }
