14	import org.springframework.samples.petclinic.repository.OwnerRepository;
15	
16	/**
17	 * Assigns the owner's {@code memberId}, the single unified identifier formatted
18	 * {@code <REGION><FY><HASH8><CHK>}:
19	 * <ul>
20	 * <li>REGION — the version-2 region code from the shared {@link CityRegions} table: the plain
21	 * postcode-derived region (or {@code UNKNOWN} when the postcode is absent or in no known range)
22	 * with the fixed {@code V2} version tag mixed in, so no member id produced under version 1 is
23	 * produced again. The tag stays inside the identifier — the user-facing locality keeps the plain
24	 * region,</li>
25	 * <li>FY — the 2-digit fiscal year (last two digits of the fiscal year containing the
26	 * business-day-adjusted {@code registrationDate}) from the shared {@link FiscalYear} rule,</li>
27	 * <li>HASH8 — the first 8 upper-case hex characters of SHA-256 over
28	 * {@code normalizedTelephone + lastName}, the same value used by the region-and-hash identity;
29	 * the telephone is normalized to E.164 via {@link OwnerTelephones} so the hash is stable
30	 * regardless of the incoming format,</li>
31	 * <li>CHK — a single Luhn check digit computed over the digits of {@code <REGION><FY><HASH8>}.</li>
32	 * </ul>
33	 * (e.g. {@code V2NSW263A7F1C2D4}).
34	 *
35	 * <p>The base member id is fully determined by the owner's own fields, but two distinct owners
36	 * could in principle hash to the same id. When the computed id collides with an existing owner's
37	 * {@code memberId}, {@code -<n>} is appended with the smallest {@code n} of 2 or more that makes it
38	 * unique, so distinct owners always end up with distinct member ids.
39	 */
40	public class AssignMemberId {
41	
